      SUBROUTINE THORDC---- CALCULATES DOUBLE INTEGRALS FOR THIRD-ORDER MATRIX ELEMENTS FORC---- A COMBINED-FUNCTION BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HSINT3.CIN'      INCLUDE 'HSLINT.CIN'      INCLUDE 'HSLIN3.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'HPINT3.CIN'      INCLUDE 'HPLINT.CIN'      INCLUDE 'HPLIN3.CIN'      INCLUDE 'H0F.CIN'      INCLUDE 'H02F.CIN'      INCLUDE 'H03F.CIN'      INCLUDE 'H04F.CIN'      INCLUDE 'H05F.CIN'      INCLUDE 'H06F.CIN'      INCLUDE 'H0L.CIN'      INCLUDE 'H02L.CIN'      INCLUDE 'H03L.CIN'      INCLUDE 'H04L.CIN'      INCLUDE 'H05L.CIN'      INCLUDE 'H0N.CIN'      INCLUDE 'H0NW.CIN'      INCLUDE 'H0P.CIN'      INCLUDE 'H0W.CIN'      INCLUDE 'H02W.CIN'      INCLUDE 'H03W.CIN'      INCLUDE 'H04W.CIN'      INCLUDE 'H05W.CIN'      INCLUDE 'H06W.CIN'      INCLUDE 'H0WF.CIN'      INCLUDE 'H02WF.CIN'      INCLUDE 'H03WF.CIN'      INCLUDE 'H04WF.CIN'      INCLUDE 'H05WF.CIN'      INCLUDE 'H06WF.CIN'      INCLUDE 'LP.CIN'      INCLUDE 'PXINT.CIN'      INCLUDE 'PCXINT.CIN'      INCLUDE 'PSXINT.CIN'      INCLUDE 'PDXINT.CIN'      INCLUDE 'PCPINT.CIN'      INCLUDE 'PSPINT.CIN'      INCLUDE 'PDPINT.CIN'      INCLUDE 'PEYINT.CIN'      INCLUDE 'PTYINT.CIN'      INCLUDE 'PEQINT.CIN'      INCLUDE 'PTQINT.CIN'      INCLUDE 'QYINT.CIN'      INCLUDE 'QCYINT.CIN'      INCLUDE 'QSYINT.CIN'      INCLUDE 'QDYINT.CIN'      INCLUDE 'QCQINT.CIN'      INCLUDE 'QSQINT.CIN'      INCLUDE 'QDQINT.CIN'      INCLUDE 'QEXINT.CIN'      INCLUDE 'QTXINT.CIN'      INCLUDE 'QEPINT.CIN'      INCLUDE 'QTPINT.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'VSINT.CIN'      INCLUDE 'VSINT3.CIN'      INCLUDE 'VSLIN3.CIN'      INCLUDE 'VPINT.CIN'      INCLUDE 'VPINT3.CIN'      INCLUDE 'VPLIN3.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'WM5N.CIN'      INCLUDE 'XXINT.CIN'      INCLUDE 'XCXINT.CIN'      INCLUDE 'XSXINT.CIN'      INCLUDE 'XDXINT.CIN'      INCLUDE 'XCPINT.CIN'      INCLUDE 'XSPINT.CIN'      INCLUDE 'XDPINT.CIN'      INCLUDE 'XEYINT.CIN'      INCLUDE 'XTYINT.CIN'      INCLUDE 'XEQINT.CIN'      INCLUDE 'XTQINT.CIN'      INCLUDE 'YYINT.CIN'      INCLUDE 'YCYINT.CIN'      INCLUDE 'YSYINT.CIN'      INCLUDE 'YDYINT.CIN'      INCLUDE 'YCQINT.CIN'      INCLUDE 'YSQINT.CIN'      INCLUDE 'YDQINT.CIN'      INCLUDE 'YEXINT.CIN'      INCLUDE 'YTXINT.CIN'      INCLUDE 'YEPINT.CIN'      INCLUDE 'YTPINT.CIN'C----------------------------------------------------------------------      REAL            TERM1C      XXI = HSDX/H02      XXC = 0.5*HSLSX/H02      IF (XPND) THEN        XXS = 1.0/120.0*L5 - WMN*H02L7/1680.        XXD = 1.0/720.0*H0L6 - WMN*H03L8/13440.      ELSE        XXS = 0.5*HSSX/H04W - 0.5*HSLCX/H02W        XXD = HSDX/H03W - 0.5*HSLSX/H03W      ENDIF      XXCC = 2./3.*HSDX/H02 + 1./3.*HSCDX/H02      XXCS = 1./3.*HSSDX/H04      IF (XPND) THEN        XXCD = 1.0/720.0*H0L6 - WMN*H03L8/4480.      ELSE        XXCD = 0.5*HSLSX/H03W - 2./3.*HSDX/H03W     1   - 1./3.*HSCDX/H03W      ENDIF      XXSS = 1./3.*HSDX2/H04      IF (XPND) THEN        XXSD = 1.0/1680.0*H0L7 - WMN*H03L9/17280.        XXDD = 1.0/6720.0*H02L8 - WMN*H04L10/86400.        XXEE = 1.0/24.0*L4 - H02L6/360.        XXET = 1.0/120.0*L5 - (NB/1260. + WMN/2520.)*H02L7        XXTT = 1.0/360.0*L6 - (NB/5040 + WMN/10080)*H02L8      ELSE        XXSD = 1./3.*HSCSX/H03W2 + 1./6.*HSSX/H05W2     1   - 0.5*HSLCX/H03W2        XXDD = 1./3.*HSCDX/H04W2 + 5./3.*HSDX/H04W2     1   - HSLSX/H04W2        XXEE = - 0.5*HSCX/H02W - 0.5*HSCX/H02F     1   + HSCY2/H02F - 2.0*NB*DISN/H02WF        XXET = - HSSX/H04F + HSCSY/H04F        XXTT = HSSY2/H04F - 2.0*HSDX/H04F      ENDIFC      XCXI = HSCDX/H02      XCXC = 0.5*HSLCS0      IF (XPND) THEN        XCXS = 1.0/120.0*L5 - 13.*WMN*H02L7/5040.        XCXD = 1.0/720.0*H0L6 - WMN*H03L8/2240.      ELSE        XCXS = - 0.5*HSLCC0/H02W + 0.5*HSCSX/H02W        XCXD = - 0.5*HSLCS0/H0W + HSCDX/H03W      ENDIF      XCXCC = 2./3.*HSCDX/H02 + 1./3.*HSCCD0/H0      XCXCS = 1./3.*HSCSD0/H0      IF (XPND) THEN        XCXCD = 1.0/720.0*H0L6 - WMN*H03L8/1680.        XCXSS = 1.0/360.0*L6 - WMN*H02L8/960.        XCXSD = 1.0/1680.0*H0L7 - WMN*H03L9/4320.        XCXDD = 1.0/6720.0*H02L8 - WMN*H04L10/17280.        XCXEE = 1.0/24.0*L4 - (NB/360. + WMN/90.)*H02L6        XCXET = 1.0/120.0*L5 - (NB/1260. + WMN/420.)*H02L7        XCXTT = 1.0/360.0*L6 - (NB/5040. + 17.*WMN/20160)*H02L8      ELSE        XCXCD = 0.5*HSLCS0/H0W - 2./3.*HSCDX/H03W     1   - 1./3.*HSCCD0/H02W        XCXSS = 1./3.*HSCDX/H04W - 1./3.*HSCCD0/H03W        XCXSD = - 0.5*HSLCC0/H03W2     1   + 1./6.*HSCSX/H03W2 + 1./3.*HSCCS0/H03W2        XCXDD = - HSLCS0/H02W2 + 5./3.*HSCDX/H04W2     1   + 1./3.*HSCCD0/H03W2        XCXEE = HSCCC2/H02F + 0.5*HSCDX/H02     1   - 0.5*HSCX/H02F - 0.5*HSCX2/H02F        XCXET = - HSCSX/H02F + HSCCS2/H02F        XCXTT = HSCSS2/H02F - 2.0*HSCX/H04WF     1   + 2.0*HSCX2/H04WF      ENDIFC      XSXI = HSSDX/H04      XSXC = 0.5*HSLSS0      IF (XPND) THEN        XSXS = 1.0/180.0*L6 - WMN*H02L8/1120.        XSXD = 1.0/1008.0*H0L7 - WMN*H03L9/6720.      ELSE        XSXS = - 0.5*HSLCS0/H02W + 0.5*HSSX2/H04W        XSXD = - 0.5*HSLSS0/H0W - HSCSX/H03W2     1   + HSSX/H05W2      ENDIF      XSXCC = 2./3.*HSSDX/H04 + 1./3.*HSCSD0/H0      XSXCS = 1./3.*HSSSD0/H0      IF (XPND) THEN        XSXCD = 1.0/1008.0*H0L7 - WMN*H03L9/3780.      ELSE        XSXCD = 0.5*HSLSS0/H0W - 2./3.*HSSDX/H05W     1   - 1./3.*HSCSD0/H02W      ENDIF      XSXSS = 1./3.*HSSDD0/H02      IF (XPND) THEN        XSXSD = 1.0/2240.0*H0*L8 - 11.*WMN*H03L10/120960.        XSXDD = 1.0/8640.0*H02L9 - 29.*WMN*H04L11/1330560.        XSXEE = 0.025*L5 - (NB/504 + WMN/280.)*H02L7        XSXET = 1.0/180.0*L6 - (NB/1680 + WMN/1344.)*H02L8        XSXTT = 1.0/504.0*L7 - (NB/6480. + 47.*WMN/181440.)*H02L9      ELSE        XSXSD = - 0.5*HSLCS0/H03W2     1   + 1./3.*HSCSS0/H03W2     2   + 1./6.*HSSX2/H05W2        XSXDD = - HSLSS0/H02W2 + 5./3.*HSSDX/H06W2     1   + 1./3.*HSCSD0/H03W2        XSXEE = 0.5*HSSDX/H04 - 0.5*HSCSX/H02F     1   + HSSCC2/H02F - 0.5*HSSX/H04F        XSXET = HSSCS2/H02F - HSSX2/H04F        XSXTT = 2.0*HSCSX/H04WF- 2.0*HSSX/H06WF     1   + HSSSS2/H02F      ENDIFC      XDXI = HSDX2/H03      XDXC = 0.5*HSLSD0      IF (XPND) THEN        XDXS = 1.0/504.0*H0L7 - 29.*WMN*H03L9/120960.        XDXD = 1.0/2688.0*H02L8 - 47.*WMN*H04L10/1209600.      ELSE        XDXS = - 0.5*HSLCD0/H02W + 0.5*HSSDX/H05W        XDXD = - 0.5*HSLSD0/H0W + HSDX2/H04W      ENDIF      XDXCC = 2./3.*HSDX2/H03 + 1./3.*HSCDD0/H0      XDXCS = 1./3.*HSSDD0/H0      IF (XPND) THEN        XDXCD = 1.0/2688.0*H02L8 - 103.*WMN*H04L10/1209600.      ELSE        XDXCD = 0.5*HSLSD0/H0W - 2./3.*HSDX2/H04W     1   - 1./3.*HSCDD0/H02W      ENDIF      XDXSS = 1./3.*HSDDD0/H02      IF (XPND) THEN        XDXSD = 1.0/5760.0*H02L9 - 11.*WMN*H04L11/403200.        XDXDD = 1.0/21600.0*H03L10 - 127.*WMN*H05L12/19958400.        XDXEE = 1.0/120.0*H0*L6 - (NB/1344. + WMN/1120.)*H03L8        XDXET = 1.0/504.0*H0L7 - (NB/4320 + 11.*WMN/60480.)*H03L9        XDXTT = 1.0/1344.0*H0*L8     1   - (NB/16200. + 113.*WMN/1814400.)*H03L10      ELSE        XDXSD = - 0.5*HSLCD0/H03W2     1   + 1./3.*HSCSD0/H03W2 + 1./6.*HSSDX/H06W2        XDXDD = - HSLSD0/H02W2 + 5./3.*HSDX2/H05W2     1   + 1./3.*HSCDD0/H03W2        XDXEE = 0.5*HSDX2/H03 - 0.5*HSCDX/H03F     1   + HSDCC2/H02F - 0.5*HSDX/H03F        XDXET = - HSSDX/H05F + HSDCS2/H02F        XDXTT = - 2.0*HSDX2/H05F + HSDSS2/H02F      ENDIFC      XCPI = HSCSX      XCPC = 0.5*HSLCC0 + 0.5*HSCSX      XCPS = 0.5*HSLCS0      IF (XPND) THEN        XCPD = 1.0/120.0*H0L5 - 13.*WMN*H03L7/5040.      ELSE        XCPD = - 0.5*HSLCC0/H0W + 0.5*HSCSX/H0W      ENDIF      XCPCC = 1./3.*HSCSX + 2./3.*HSCCS0      XCPCS = 1./3.*HSCDX/H02 + 2./3.*HSCCD0/H0      IF (XPND) THEN        XCPCD = 1.0/120.0*H0L5 - 19.*WMN*H03L7/5040.      ELSE        XCPCD = 0.5*HSLCC0/H0W + 1./6.*HSCSX/H0W     1   - 2./3.*HSCCS0/H0W      ENDIF      XCPSS = 2./3.*HSCSD0/H0      IF (XPND) THEN        XCPSD = 1.0/240.0*H0L6 - 11.*WMN*H03L8/6720.        XCPDD = 1.0/840.0*H02L7 - WMN*H04L9/2160.      ELSE        XCPSD = 0.5*HSLCS0/H0W - 1./3.*HSCDX/H03W     1   - 2./3.*HSCCD0/H02W        XCPDD = - HSLCC0/H02W2 + 1./3.*HSCSX/H02W2     1   + 2./3.*HSCCS0/H02W2      ENDIF      XCPEE = 0.5*WMN*HSCSX/WM5N - 2.*NB*HSCCS2/WM5N     1 + 0.5*HSCSX      IF (XPND) THEN        XCPET = 1.0/24.0*L4 - (NB/180. + WMN/90.)*H02L6        XCPTT = 1.0/60.0*L5 - (NB/630. + WMN/210.)*H02L7      ELSE        XCPET = 2.*HSCCC2/H02F - HSCX/H02F     1   - HSCX2/H02F        XCPTT = - 2.0*HSCSX/H02F + 2.*HSCCS2/H02F      ENDIFC      XSPI = HSSX2/H02      XSPC = 0.5*HSLCS0 + 0.5*HSSX2/H02      XSPS = 0.5*HSLSS0      IF (XPND) THEN        XSPD = 1.0/180.0*H0L6 - WMN*H03L8/1120.      ELSE        XSPD = - 0.5*HSLCS0/H0W + 0.5*HSSX2/H03W      ENDIF      XSPCC = 2./3.*HSCSS0  + 1./3.*HSSX2/H02      XSPCS = 1./3.*HSSDX/H04 + 2./3.*HSCSD0/H0      IF (XPND) THEN        XSPCD = 1.0/180.0*H0L6 - WMN*H03L8/560.      ELSE        XSPCD = 0.5*HSLCS0/H0W - 2./3.*HSCSS0/H0W     1   + 1./6.*HSSX2/H03W      ENDIF      XSPSS = 2./3.*HSSSD0/H0      IF (XPND) THEN        XSPSD = 1.0/336.0*H0L7 - 41.*WMN*H03L9/60480.        XSPDD = 1.0/1120.0*H02L8 - 11.*WMN*H04L10/60480.      ELSE        XSPSD = 0.5*HSLSS0/H0W - 2./3.*HSCSD0/H02W     1   - 1./3.*HSSDX/H05W        XSPDD = - HSLCS0/H02W2 + 2./3.*HSCSS0/H02W2     1   + 1./3.*HSSX2/H04W2      ENDIF      XSPEE = - 2.*NB*HSSCS2/WM5N + 0.5*HSSX2/H02     1 + 0.5*WMN*HSSX2/H02F      IF (XPND) THEN        XSPET = 0.025*L5 - (NB/252. + WMN/280.)*H02L7        XSPTT = 1.0/90.0*L6 - (NB/840. + WMN/672.)*H02L8      ELSE        XSPET = - HSCSX/H02F + 2.*HSSCC2/H02F     1   - HSSX/H04F        XSPTT = - 2.0*HSSX2/H04F + 2.*HSSCS2/H02F      ENDIFC      XDPI = HSSDX/H03      XDPC = 0.5*HSLCD0 + 0.5*HSSDX/H03      XDPS = 0.5*HSLSD0      IF (XPND) THEN        XDPD = 1.0/504.0*H02L7 - 29.*WMN*H04L9/120960.      ELSE        XDPD = - 0.5*HSLCD0/H0W + 0.5*HSSDX/H04W      ENDIF      XDPCC = 2./3.*HSCSD0 + 1./3.*HSSDX/H03      XDPCS = 1./3.*HSDX2/H03 + 2./3.*HSCDD0/H0      IF (XPND) THEN        XDPCD = 1.0/504.0*H02L7 - 71.*WMN*H04L9/120960.      ELSE        XDPCD = 0.5*HSLCD0/H0W - 2./3.*HSCSD0/H0W     1   + 1./6.*HSSDX/H04W      ENDIF      XDPSS = 2./3.*HSSDD0/H0W      IF (XPND) THEN        XDPSD = 1.0/896.0*H02L8 - 253.*WMN*H04L10/1209600.        XDPDD = 1.0/2880.0*H03L9 - 11.*WMN*H05L11/201600.      ELSE        XDPSD = 0.5*HSLSD0/H0W - 2./3.*HSCDD0/H02W     1   - 1./3.*HSDX2/H04W        XDPDD = - HSLCD0/H02W2 + 2./3.*HSCSD0/H02W2     1   + 1./3.*HSSDX/H05W2      ENDIF      XDPEE = - 2.*NB*HSDCS2/WM5N + 0.5*HSSDX/H03     1 + 0.5*HSSDX*WMN/H03F      IF (XPND) THEN        XDPET = 1.0/120.0*H0L6 - (NB/672. + WMN/1120.)*H03L8        XDPTT = 1.0/252.0*H0L7 - (NB/2160. + 11.*WMN/30240.)*H03L9      ELSE        XDPET = - HSCDX/H03F + 2.*HSDCC2/H02F     1   - HSDX/H03F        XDPTT = - 2.0*HSSDX/H05F + 2.*HSDCS2/H02F      ENDIFC      XEYE = 0.5*HSLCS2      IF (XPND) THEN        XEYT = 1.0/120.0*L5 - (NB/420. + WMN/5040.)*H02L7        XEYCE = 1.0/24.0*L4 - (NB/90. + WMN/360.)*H02L6        XEYCT = 1.0/120.0*L5 - (NB/420. + WMN/1260.)*H02L7        XEYSE = 1.0/120.0*L5 - (NB/360. + WMN/2520.)*H02L7        XEYST = 1.0/360.0*L6 - (NB/1120. + WMN/6720.)*H02L8        XEYDE = 1.0/720.0*H0L6 - (11.*NB + WMN)*H03L8/20160.      ELSE        IF (NB .EQ. 0.0) XEYT = 1./6.*HSL3/H04        IF (NB .NE. 0.0)     1    XEYT = - 0.5*HSLCC2/H02N + 0.5*HSCSY/H04N        XEYCE = - 2.0*NB*HSSCS2/WM5N - HSCCC2/H02F     1   + HSCY2/H02F        XEYCT = 2.0*HSSCC2/H02F - HSCCS2/H02F     1   - HSCSY/H04F        XEYSE = 0.5*HSCCS2/H02F + 0.5*HSDCS2/H0     1   + 0.5*HSCSY/H04F - HSSCC2/H02F        XEYST = 2.0*HSDCC2/H03F - HSSCS2/H02F        XEYDE = 0.5*HSLCS2/H0W + 2.0*NB*HSSCS2/H0WF     1   - HSDCC2/H02F      ENDIF      IF (XPND) THEN        XEYDT = 1.0/1680.0*H0L7 - (19.*NB/90720. + WMN/45360.)*H03L9      ELSE IF (NB .EQ. 0.0) THEN        XEYDT = 1./6.*HSL3/H05 - 2.0*HSSCC2/H03     1   + HSCCS2/H03 + HSCSY/H05      ELSE        XEYDT = - 0.5*HSLCC2/H03NW     1   + 0.5*HSCSY/H05NW - 2.0*HSSCC2/H03WF     2   + HSCCS2/H03WF + HSCSY/H05WF      ENDIFC      XTYE = 0.5*HSLSS2      IF (XPND) THEN        XTYT = 1.0/180.0*L6 - (NB/1260. + WMN/10080.)*H02L8        XTYCE = 0.025*L5 - (NB/252. + WMN/630.)*H02L7        XTYCT = 1.0/180.0*L6 - (NB/1260. + 11.*WMN/20160.)*H02L8        XTYSE = 1.0/180.0*L6 - (11.*NB/10080. + WMN/4032.)*H02L8        XTYST = 1.0/504.0*L7 - (NB/3240. + 19.*WMN/181440.)*H02L9        XTYDE = 1.0/1008.0*H0L7 - (NB/4320. + WMN/30240.)*H03L9      ELSE        IF (NB .EQ. 0.0) THEN          XTYT = 1.0/6.0*HSL4/H06        ELSE          XTYT = 0.5*HSSY2/H04N - 0.5*HSLCS2/H02N        ENDIF        XTYCE = - HSCCS2/H02F + HSCSY/H04F     1   - 2.0*NB*HSSSS2/WM5N        XTYCT = 2.0*HSSCS2/H02F - HSCSS2/H02F     1   - HSSY2/H04F        XTYSE = 0.5*HSDSS2/H0 - HSSCS2/H02F     1   + 0.5*HSCSS2/H02F + 0.5*HSSY2/H04F        XTYST = - 2.0*HSCCS2/H04WF     1   + 2.0*HSCSY/H06WF - HSSSS2/H02F        XTYDE = 0.5*HSLSS2/H0W - HSDCS2/H02F     1   + 2.0*NB*HSSSS2/H0WF      ENDIF      IF (XPND) THEN        XTYDT = 1.0/2240.0*H0*L8     1          - (17.*NB/226800. + 29.*WMN/1814400.)*H03L10      ELSE IF (NB .EQ. 0.0) THEN        XTYDT = HSSY2/H05 + HSCSS2/H03 - 2.0*HSSCS2/H03     1   + 1.0/6.0*HSL4/H07      ELSE        XTYDT = 0.5*HSSY2/H05NW     1   - 0.5*HSLCS2/H03NW - 2.0*HSSCS2/H03WF     2   + HSCSS2/H03WF + HSSY2/H05WF      ENDIFC      XEQE = 0.5*HSLCC2 + 0.5*HSCSY/H02      XEQT = 0.5*HSLCS2      XEQCE = - NB*HSCCS2/WM5N - NB*HSCSY/H02F     1 + 0.5*HSSCC2 + 0.5*WMN*HSSCC2/WM5N      IF (XPND) THEN        XEQCT = 1.0/24.0*L4 - (NB/90. + WMN/180.)*H02L6        XEQSE = 1.0/24.0*L4 - (NB/90. + WMN/360.)*H02L6        XEQST = 1.0/60.0*L5 - (13.*NB/2520. + WMN/840.)*H02L7        XEQDE = 1.0/120.0*H0L5 - (17.*NB/5040. + WMN/2520.)*H03L7        XEQDT = 1.0/240.0*H0L6 - (29.*NB/20160. + WMN/5040.)*H03L8      ELSE        XEQCT = 0.5*HSSCS2 + 0.5*HSSCS2*WMN/WM5N     1   + HSCCC2/H02F - HSCY2/H02F        XEQSE = 0.5*HSDCC2/H0 - NB*HSSCS2/WM5N     1   - 0.5*HSCCC2/H02F + 0.5*HSCY2/H02F        XEQST = 0.5*HSDCS2/H0 - 0.5*HSCCS2/H02F     1   - 0.5*HSCSY/H04F + HSSCC2/H02F        XEQDE = NB*HSCCS2/H0WF + NB*HSCSY/H03WF     1   + 0.5*HSLCC2/H0W + 0.5*HSCSY/H03W     2   - 0.5*HSSCC2/H0W - 0.5*HSSCC2/H0F        XEQDT = 0.5*HSLCS2/H0W - 0.5*HSSCS2/H0W     1   - 0.5*HSSCS2/H0F + HSDCC2/H02F      ENDIFC      XTQE = 0.5*HSLCS2 + 0.5*HSSY2/H02      XTQT = 0.5*HSLSS2      XTQCE = - NB*HSCSS2/WM5N - NB*HSSY2/H02F     1 + 0.5*HSSCS2 + 0.5*WMN*HSSCS2/WM5N      IF (XPND) THEN        XTQCT = 0.025*L5 - (NB/252. + WMN/280.)*H02L7        XTQSE = 0.025*L5 - (NB/168. + WMN/630.)*H02L7        XTQST = 1.0/90.0*L6 - (19.*NB/10080. + WMN/1260.)*H02L8        XTQDE = 1.0/180.0*H0L6 - (31.*NB/20160. + WMN/4032.)*H03L8        XTQDT = 1.0/336.0*H0L7     1          - (7.*NB/12960. + 5.*WMN/36288.)*H03L9      ELSE        XTQCT = HSCCS2/H02F - HSCSY/H04F     1   + 0.5*HSSSS2 + 0.5*WMN*HSSSS2/WM5N        XTQSE = 0.5*HSDCS2/H0 - NB*HSSSS2/WM5N     1   - 0.5*HSCCS2/H02F + 0.5*HSCSY/H04F        XTQST = 0.5*HSDSS2/H0 + HSSCS2/H02F     1   - 0.5*HSCSS2/H02F - 0.5*HSSY2/H04F        XTQDE = NB*HSCSS2/H0WF + NB*HSSY2/H03WF     1   + 0.5*HSLCS2/H0W - 0.5*HSSCS2/H0W     2   - 0.5*HSSCS2/H0F + 0.5*HSSY2/H03W        XTQDT = 0.5*HSLSS2/H0W - 0.5*HSSSS2/H0W     1   + HSDCS2/H02F - 0.5*HSSSS2/H0F      ENDIFC      PXI = HPDX/H02      PXC = 0.5*HPLSX      IF (XPND) THEN        P