/H03W        PCXSD = - 0.5*HPLCC0/H03W2     1   + 1./6.*HPCSX/H03W2 + 1./3.*HPCCS0/H03W2        PCXDD = - HPLCS0/H02W2 + 5./3.*HPCDX/H04W2     1   + 1./3.*HPCCD0/H03W2        PCXEE = HPCCC2/H02F + 0.5*HPCDX/H02     1   - 0.5*HPCX/H02F - 0.5*HPCX2/H02F        PCXET = - HPCSX/H02F + HPCCS2/H02F        PCXTT = HPCSS2/H02F - 2.0*HPCX/H04WF     1   + 2.0*HPCX2/H04WF      ENDIFC      PSXI = HPSDX/H02      PSXC = 0.5*HPLSS0      IF (XPND) THEN        PSXS = 1.0/30.0*L5 - WMN*H02L7/140.        PSXD = 1.0/144.0*H0L6 - 3.*WMN*H03L8/2240.      ELSE        PSXS = - 0.5*HPLCS0/H02W + 0.5*HPSX2/H02W        PSXD = - 0.5*HPLSS0/H0W - HPCSX/H03W2     1   + HPSX/H03W2      ENDIF      PSXCC = 2./3.*HPSDX/H02 + 1./3.*HPCSD0/H0      PSXCS = 1./3.*HPSSD0/H0      IF (XPND) THEN        PSXCD = 1.0/144.0*H0L6 - WMN*H03L8/420.      ELSE        PSXCD = 0.5*HPLSS0/H0W - 2./3.*HPSDX/H03W     1   - 1./3.*HPCSD0/H02W      ENDIF      PSXSS = 1./3.*HPSDD0/H02      IF (XPND) THEN        PSXSD = 1.0/280.0*H0L7 - 11.*WMN*H03L9/12096.        PSXDD = 1.0/960.0*H02L8 - 29.*WMN*H04L10/120960.        PSXEE = 0.125*L4 - (NB/72. + WMN/40.)*H02L6        PSXET = 1.0/30.0*L5 - (NB/210. + WMN/168.)*H02L7        PSXTT = 1.0/72.0*L6 - (NB/720. + 47.*WMN/20160.)*H02L8      ELSE        PSXSD = - 0.5*HPLCS0/H03W2     1   + 1./3.*HPCSS0/H03W2 + 1./6.*HPSX2/H03W2        PSXDD = - HPLSS0/H02W2 + 5./3.*HPSDX/H04W2     1   + 1./3.*HPCSD0/H03W2        PSXEE = 0.5*HPSDX/H02 - 0.5*HPCSX/H02F     1   + HPSCC2/H02F - 0.5*HPSX/H02F        PSXET = HPSCS2/H02F - HPSX2/H02F        PSXTT = 2.0*HPCSX/H04WF- 2.0*HPSX/H04WF     1   + HPSSS2/H02F      ENDIFC      PDXI = HPDX2/H03      PDXC = 0.5*HPLSD0      IF (XPND) THEN        PDXS = 1.0/72.0*H0L6 - 29.*WMN*H03L8/13440.        PDXD = 1.0/336.0*H02L7 - 47.*WMN*H04L9/120960.      ELSE        PDXS = - 0.5*HPLCD0/H02W + 0.5*HPSDX/H03W        PDXD = - 0.5*HPLSD0/H0W + HPDX2/H04W      ENDIF      PDXCC = 2./3.*HPDX2/H03 + 1./3.*HPCDD0/H0      PDXCS = 1./3.*HPSDD0/H0      IF (XPND) THEN        PDXCD = 1.0/336.0*H02L7 - 103.*WMN*H04L9/120960.      ELSE        PDXCD = 0.5*HPLSD0/H0W - 2./3.*HPDX2/H04W     1   - 1./3.*HPCDD0/H02W      ENDIF      PDXSS = 1./3.*HPDDD0/H02      IF (XPND) THEN        PDXSD = 1.0/640.0*H02L8 - 121.*WMN*H04L10/403200.        PDXDD = 1.0/2160.0*H03L9 - 127.*WMN*H05L11/1663200.        PDXEE = 0.05*H0L5 - (NB/168. + WMN/140.)*H03L7        PDXET = 1.0/72.0*H0L6 - (NB/480. + 11.*WMN/6720.)*H03L8        PDXTT = 1.0/168.0*H0L7 - (NB/1620. + 113.*WMN/181440.)*H03L9      ELSE        PDXSD = - 0.5*HPLCD0/H03W2     1   + 1./3.*HPCSD0/H03W2 + 1./6.*HPSDX/H04W2        PDXDD = - HPLSD0/H02W2 + 5./3.*HPDX2/H05W2     1   + 1./3.*HPCDD0/H03W2        PDXEE = 0.5*HPDX2/H03 - 0.5*HPCDX/H03F     1   + HPDCC2/H02F - 0.5*HPDX/H03F        PDXET = - HPSDX/H03F + HPDCS2/H02F        PDXTT = - 2.0*HPDX2/H05F + HPDSS2/H02F      ENDIFC      PCPI = HPCSX      PCPC = 0.5*HPLCC0 + 0.5*HPCSX      PCPS = 0.5*HPLCS0      IF (XPND) THEN        PCPD = 1.0/24.0*H0*L4 - 13.*WMN*H03L6/720.      ELSE        PCPD = - 0.5*HPLCC0/H0W + 0.5*HPCSX/H0W      ENDIF      PCPCC = 1./3.*HPCSX + 2./3.*HPCCS0      PCPCS = 1./3.*HPCDX/H02 + 2./3.*HPCCD0/H0      IF (XPND) THEN        PCPCD = 1.0/24.0*H0*L4 - 19.*WMN*H03L6/720.      ELSE        PCPCD = 0.5*HPLCC0/H0W + 1./6.*HPCSX/H0W     1   - 2./3.*HPCCS0/H0W      ENDIF      PCPSS = 2./3.*HPCSD0/H0      IF (XPND) THEN        PCPSD = 0.025*H0L5 - 11.*WMN*H03L7/840.        PCPDD = 1.0/120.0*H02L6 - WMN*H04L8/240.      ELSE        PCPSD = 0.5*HPLCS0/H0W - 1./3.*HPCDX/H03W     1   - 2./3.*HPCCD0/H02W        PCPDD = - HPLCC0/H02W2 + 1./3.*HPCSX/H02W2     1   + 2./3.*HPCCS0/H02W2      ENDIF      PCPEE = 0.5*WMN*HPCSX/WM5N - 2.*NB*HPCCS2/WM5N     1 + 0.5*HPCSX      IF (XPND) THEN        PCPET = 1.0/6.0*L3 - (NB/30. + WMN/15.)*H02L5        PCPTT = 1.0/12.0*L4 - (NB/90. + WMN/30.)*H02L6      ELSE        PCPET = 2.*HPCCC2/H02F - HPCX/H02F     1   - HPCX2/H02F        PCPTT = - 2.0*HPCSX/H02F + 2.0*HPCCS2/H02F      ENDIFC      PSPI = HPSX2      PSPC = 0.5*HPLCS0 + 0.5*HPSX2      PSPS = 0.5*HPLSS0      IF (XPND) THEN        PSPD = 1.0/30.0*H0L5 - WMN*H03L7/140.      ELSE        PSPD = - 0.5*HPLCS0/H0W + 0.5*HPSX2/H0W      ENDIF      PSPCC = 2./3.*HPCSS0  + 1./3.*HPSX2      PSPCS = 1./3.*HPSDX/H02 + 2./3.*HPCSD0/H0      IF (XPND) THEN        PSPCD = 1.0/30.0*H0L5 - WMN*H03L7/70.      ELSE        PSPCD = 0.5*HPLCS0/H0W - 2./3.*HPCSS0/H0W     1   + 1./6.*HPSX2/H0W      ENDIF      PSPSS = 2./3.*HPSSD0/H0      IF (XPND) THEN        PSPSD = 1.0/48.0*H0L6 - 41.*WMN*H03L8/6720.        PSPDD = 1.0/140.0*H02L7 - 11.*WMN*H04L9/6048.      ELSE        PSPSD = 0.5*HPLSS0/H0W - 2./3.*HPCSD0/H02W     1   - 1./3.*HPSDX/H03W        PSPDD = - HPLCS0/H02W2 + 2./3.*HPCSS0/H02W2     1   + 1./3.*HPSX2/H02W2      ENDIF      PSPEE = - 2.*NB*HPSCS2/WM5N + 0.5*HPSX2     1 + 0.5*WMN*HPSX2/WM5N      IF (XPND) THEN        PSPET = 0.125*L4 - (NB/36 + WMN/40.)*H02L6        PSPTT = 1.0/15.0*L5 - (NB/105. + WMN/84.)*H02L7      ELSE        PSPET = - HPCSX/H02F + 2.*HPSCC2/H02F     1   - HPSX/H02F        PSPTT = - 2.0*HPSX2/H02F + 2.*HPSCS2/H02F      ENDIFC      PDPI = HPSDX/H0      PDPC = 0.5*HPLCD0 + 0.5*HPSDX/H0      PDPS = 0.5*HPLSD0      IF (XPND) THEN        PDPD = 1.0/72.0*H02L6 - 29.*WMN*H04L8/13440.      ELSE        PDPD = - 0.5*HPLCD0/H0W + 0.5*HPSDX/H02W      ENDIF      PDPCC = 2./3.*HPCSD0 + 1./3.*HPSDX/H0      PDPCS = 1./3.*HPDX2/H03 + 2./3.*HPCDD0/H0      IF (XPND) THEN        PDPCD = 1.0/72.0*H02L6 - 71.*WMN*H04L8/13440.      ELSE        PDPCD = 0.5*HPLCD0/H0W - 2./3.*HPCSD0/H0W     1   + 1./6.*HPSDX/H02W      ENDIF      PDPSS = 2./3.*HPSDD0/H0W      IF (XPND) THEN        PDPSD = 1.0/112.0*H02L7 - 253.*WMN*H04L9/120960.        PDPDD = 1.0/320.0*H03L8 - 121.*WMN*H05L10/201600.      ELSE        PDPSD = 0.5*HPLSD0/H0W - 2./3.*HPCDD0/H02W     1   - 1./3.*HPDX2/H04W        PDPDD = - HPLCD0/H02W2 + 2./3.*HPCSD0/H02W2     1   + 1./3.*HPSDX/H03W2      ENDIF      PDPEE = - 2.*NB*HPDCS2/WM5N + 0.5*HPSDX/H0     1 + 0.5*HPSDX*WMN/H0F      IF (XPND) THEN        PDPET = 0.05*H0L5 - (NB/84. + WMN/140.)*H03L7        PDPTT = 1.0/36.0*H0L6 - (NB/240. + 11.*WMN/3360.)*H03L8      ELSE        PDPET = - HPCDX/H03F + 2.*HPDCC2/H02F     1   - HPDX/H03F        PDPTT = - 2.0*HPSDX/H03F + 2.*HPDCS2/H02F      ENDIFC      PEYE = 0.5*HPLCS2      IF (XPND) THEN        PEYT = 1/24.0*L4 - (NB/60. + WMN/720.)*H02L6        PEYCE = 1.0/6.0*L3 - (NB/15. + WMN/60.)*H02L5        PEYCT = 1.0/24.0*L4 - (NB/60. + WMN/180.)*H02L6        PEYSE = 1.0/24.0*L4 - (7.*NB/360. + WMN/360.)*H02L6        PEYST = 1.0/60.0*L5 - (NB/140. + WMN/840.)*H02L7        PEYDE = 1.0/120.0*H0L5 - (11.*NB + WMN)*H03L7/2520.        PEYDT = 1.0/240.0*H0L6 - (19.*NB/10080. + WMN/5040.)*H03L8      ELSE        IF (NB .EQ. 0.0) THEN          PEYT = 1.0/6.0*HPL3        ELSE          PEYT = - 0.5*HPLCC2/(NB*H02) + 0.5*HPCSY/(NB*H02)        ENDIF        PEYCE = - 2.0*NB*HPSCS2/WM5N - HPCCC2/H02F     1   + HPCY2/H02F        PEYCT = 2.0*HPSCC2/H02F - HPCCS2/H02F     1   - HPCSY/H02F        PEYSE = 0.5*HPCCS2/H02F + 0.5*HPDCS2/H0     1   + 0.5*HPCSY/H02F - HPSCC2/H02F        PEYST = 2.0*HPDCC2/H03F - HPSCS2/H02F        PEYDE = 0.5*HPLCS2/H0W + 2.0*NB*HPSCS2/H0WF     1   - HPDCC2/H02F        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*HPL3/H0W        IF (NB .NE. 0.0)     1   TERM1 = - 0.5*HPLCC2/H03NW + 0.5*HPCSY/H03NW        PEYDT = TERM1 - 2.0*HPSCC2/H03WF     1   + HPCCS2/H03WF + HPCSY/H03WF      ENDIFC      PTYE = 0.5*HPLSS2      IF (XPND) THEN        PTYT = 1.0/30.0*L5 - (2.*NB/315. + WMN/1260.)*H02L7        PTYCE = 0.125*L4 - (NB/36. + WMN/90.)*H02L6        PTYCT = 1.0/30.0*L5 - (2.*NB/315. + 11.*WMN/2520.)*H02L7        PTYSE = 1.0/30.0*L5 - (11.*NB/1260. + WMN/504.)*H02L7        PTYST = 1.0/72.0*L6 - (NB/360. + 19.*WMN/20160.)*H02L8        PTYDE = 1.0/144.0*H0L6 - (NB/480. + WMN/3360.)*H03L8        PTYDT = 1.0/280.0*H0L7     1          - (17.*NB/22680. + 29.*WMN/181440.)*H03L9      ELSE        IF (NB .EQ. 0.0) PTYT = 1.0/6.0*HPL4        IF (NB .NE. 0.0) PTYT = 0.5*HPSY2/H04N     1   - 0.5*HPLCS2/H02N        PTYCE = - HPCCS2/H02F + HPCSY/H02F     1   - 2.0*NB*HPSSS2/WM5N        PTYCT = 2.0*HPSCS2/H02F - HPCSS2/H02F     1   - HPSY2/H04F        PTYSE = 0.5*HPDSS2/H0 - HPSCS2/H02F     1   + 0.5*HPCSS2/H02F + 0.5*HPSY2/H04F        PTYST = - 2.0*HPCCS2/H04WF     1   + 2.0*HPCSY/H04WF - HPSSS2/H02F        PTYDE = 0.5*HPLSS2/H0W - HPDCS2/H02F     1   + 2.0*NB*HPSSS2/H0WF        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*HPL4/H0W        IF (NB .NE. 0.0) TERM1 = 0.5*HPSY2/H05NW     1   - 0.5*HPLCS2/H03NW        PTYDT = TERM1 - 2.0*HPSCS2/H03WF     1   + HPCSS2/H03WF + HPSY2/H05WF      ENDIFC      PEQE = 0.5*HPLCC2 + 0.5*HPCSY      PEQT = 0.5*HPLCS2      PEQCE = - NB*HPCCS2/WM5N - NB*HPCSY/WM5N     1 + 0.5*HPSCC2 + 0.5*WMN*HPSCC2/WM5N      IF (XPND) THEN        PEQCT = 1.0/6.0*L3 - (NB/15. + WMN/30.)*H02L5        PEQSE = 1.0/6.0*L3 - (NB/12. + WMN/60.)*H02L5        PEQST = 1.0/12.0*L4 - (13.*NB/360. + WMN/120.)*H02L6        PEQDE = 1.0/24.0*H0*L4 - (17.*NB/720. + WMN/360.)*H03L6        PEQDT = 0.025*H0L5 - (29.*NB/2520. + WMN/630.)*H03L7      ELSE        PEQCT = 0.5*HPSCS2 + 0.5*HPSCS2*WMN/WM5N     1   + HPCCC2/H02F - HPCY2/H02F        PEQSE = 0.5*HPDCC2/H0 - NB*HPSCS2/WM5N     1   - 0.5*HPCCC2/H02F + 0.5*HPCY2/H02F        PEQST = 0.5*HPDCS2/H0 - 0.5*HPCCS2/H02F     1   - 0.5*HPCSY/H02F + HPSCC2/H02F        PEQDE = NB*HPCCS2/H0WF + NB*HPCSY/H0WF     1   + 0.5*HPLCC2/H0W + 0.5*HPCSY/H0W     2   - 0.5*HPSCC2/H0W - 0.5*HPSCC2/H0F        PEQDT = 0.5*HPLCS2/H0W - 0.5*HPSCS2/H0W     1   - 0.5*HPSCS2/H0F + HPDCC2/H02F      ENDIFC      PTQE = 0.5*HPLCS2 + 0.5*HPSY2/H02      PTQT = 0.5*HPLSS2      PTQCE = - NB*HPCSS2/WM5N - NB*HPSY2/H02F     1 + 0.5*HPSCS2 + 0.5*WMN*HPSCS2/WM5N      IF (XPND) THEN        PTQCT = 0.125*L4 - (NB/36. + WMN/40.)*H02L6        PTQSE = 0.125*L4 - (NB/24. + WMN/90.)*H02L6        PTQST = 1.0/15.0*L5 - (19.*NB/1260. + 2.*WMN/315.)*H02L7        PTQDE = 1.0/30.0*H0L5 - (31.*NB/2520. + WMN/504.)*H03L7        PTQDT = 1.0/48.0*H0L6 - (7.*NB/1440. + 5.*WMN/4032.)*H03L8      ELSE        PTQCT = HPCCS2/H02F - HPCSY/H02F     1   + 0.5*HPSSS2 + 0.5*WMN*HPSSS2/WM5N        PTQSE = 0.5*HPDCS2/H0 - NB*HPSSS2/WM5N     1   - 0.5*HPCCS2/H02F + 0.5*HPCSY/H02F        PTQST = 0.5*HPDSS2/H0 + HPSCS2/H02F     1   - 0.5*HPCSS2/H02F - 0.5*HPSY2/H04F        PTQDE = NB*HPCSS2/H0WF + NB*HPSY2/H03WF     1   + 0.5*HPLCS2/H0W - 0.5*HPSCS2/H0W     2   - 0.5*HPSCS2/H0F + 0.5*HPSY2/H03W        PTQDT = 0.5*HPLSS2/H0W - 0.5*HPSSS2/H0W     1   + HPDCS2/H02F - 0.5*HPSSS2/H0F      ENDIFC      YYE = 0.5*VSLSY      IF (XPND .OR. NB .EQ. 0.0) YYT = L5/120.0      IF (.NOT. XPND .AND. NB .NE. 0.0)     1 YYT = 0.5*VSSY/(NB*H04) - 0.5*VSLCY/(NB*H02)      YYCE = WMN*VSDCM/H02F - 2.0*NB*VSSSM/H02F      IF (XPND) THEN        YYCT = 1.0/120.0*L5 - 1.0/1680.*H02L7        YYSE = 1.0/120.0*L5 - (NB/1008. + WMN/5040.)*H02L7        YYST = 1.0/360.0*L6 - (NB/5040. + WMN/10080.)*H02L8        YYDE = 1.0/720.0*H0L6 - (NB/5040. + WMN/40320.)*H03L8        YYDT = 1.0/1680.0*H0L7 - (NB/22680. + WMN/72576.)*H03L9      ELSE        YYCT = 2.0*VSSCM/H04F - VSCSM/H04F     1   - VSSY/H04F        YYSE = 0.5*VSDSM/H04 - VSSCM/H04F     1   + 0.5*VSCSM/H04F + 0.5*VSSY/H04F        YYST = 2.0*VSDCM/H04F - VSSSM/H04F        YYDE = 0.5*VSLSY/H0W - VSDCM/H03F     1   + 2.0*NB*VSSSM/H03WF        IF (NB .EQ. 0.0) TERM1 = 1.0/120.0*L5/H0        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VSSY/(NB*H05*WMN) - 0.5*VSLCY/(NB*H03*WMN)        YYDT = TERM1     1   - 2.0*VSSCM/H05WF + VSCSM/H05WF     2   + VSSY/H05WF      ENDIFC      YCYE = 0.5*VSLCS1      IF (XPND) THEN        YCYT = 1.0/120.0*L5 - (NB/1680. + WMN/504.)*H02L7        YCYCE = 1.0/24.0*L4 - (NB/240. + 7.*WMN/720.)*H02L6        YCYCT = 1.0/120.0*L5 - (NB/1680. + 13.*WMN/5040.)*H02L7        YCYSE = 1.0/120.0*L5 - (NB/1008. + 11.*WMN/5040.)*H02L7        YCYST = 1.0/360.0*L6 - (NB/5040. + 17.*WMN/20160.)*H02L8        YCYDE = 1.0/720.0*H0L6 - (NB/5040. + WMN/2520.)*H03L8      ELSE        IF (NB .EQ. 0.0) YCYT = 1.0/6.0*VSL3CX        IF (NB .NE. 0.0) YCYT = 0.5*VSCSM/H04N     1   - 0.5*VSLCC1/H02N        YCYCE = VSCCM/H02F - VSCCC1/H02F     1   - 2.0*NB*VSCSS1/WM5N        YCYCT = 2.0*VSCSC1/H02F - VSCSM/H04F     1   - VSCCS1/H02F        YCYSE = 0.5*VSCDS1/H0 - VSCSC1/H02F     1   + 0.5*VSCSM/H04F + 0.5*VSCCS1/H02F        YCYST = 2.0*VSCDC1/H03F - VSCSS1/H02F        YCYDE = 0.5*VSLCS1/H0W - VSCDC1/H02F     1   + 2.0*NB*VSCSS1/H0WF      ENDIF      IF (XPND) THEN        YCYDT = 1.0/1680.0*H0L7 - (NB/22680. + 17.*WMN/90720.)*H03L9      ELSE        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*VSL3CX/H0        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VSCSM/H05NW - 0.5*VSLCC1/H03NW        YCYDT = TERM1     1   - 2.0*VSCSC1/H03WF + VSCSM/H05WF     2   + VSCCS1/H03WF      ENDIFC      YSYE = 0.5*VSLSS1      IF (XPND) THEN        YSYT = 1.0/180.0*L6 - (NB/2520. + WMN/2016.)*H02L8        YSYCE = 0.025*L5 - (13.*NB/5040. + WMN/336.)*H02L7        YSYCT = 1.0/180.0*L6 - (NB/2520. + 19.*WMN/20160.)*H02L8        YSYSE = 1.0/180.0*L6 - (NB/1440. + 13.*WMN/20160.)*H02L8        YSYST = 1.0/504.0*L7 - (13.*NB/90720. + 7.*WMN/25920.)*H02L9        YSYDE = 1.0/1008.0*H0L7 - (NB/6720. + WMN/8640.)*H03L9        YSYDT = 1.0/2240.0*H0*L8     1          - (61.*NB/1814400. + 13.*WMN/226800.)*H03L10      ELSE        IF (NB .EQ. 0.0) YSYT = 1.0/6.0*VSL3SX        IF (NB .NE. 0.0) YSYT = 0.5*VSSSM/H04N     1   - 0.5*VSLSC1/H02N        YSYCE = VSSCM/H04F - VSCSC1/H02F     1   - 2.0*NB*VSSSS1/WM5N        YSYCT = 2.0*VSSSC1/H02F - VSCSS1/H02F     1   - VSSSM/H04F        YSYSE = 0.5*VSSDS1/H0 - VSSSC1/H02F     1   + 0.5*VSCSS1/H02F + 0.5*VSSSM/H04F        YSYST = 2.0*VSSDC1/H03F - VSSSS1/H02F        YSYDE = 0.5*VSLSS1/H0W - VSSDC1/H02F     1   - 0.5*VSSSS1/H0W + 0.5*VSSSS1/H0F        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*VSL3SX/H0        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VSSSM/H05NW - 0.5*VSLSC1/H03NW        YSYDT = TERM1     1   - 2.0*VSSSC1/H03WF + VSCSS1/H03WF     2   + VSSSM/H05WF      ENDIFC      YDYE = 0.5*VSLDS1      IF (XPND) THEN        YDYT = 1.0/504.0*H0L7 - (13.*NB/90720. + WMN/10368.)*H03L9        YDYCE = 1.0/120.0*H0L6 - (NB/1120. + WMN/1344.)*H03L8        YDYCT = 1.0/504.0*H0L7     1          - (13.*NB/90720. + 7.*WMN/25920.)*H03L9        YDYSE = 1.0/504.0*H0L7 - (47.*NB/181440. + WMN/6480.)*H03L9        YDYST = 1.0/1344.0*H0*L8     1          - (11.*NB/201600. + WMN/14400.)*H03L10        YDYDE = 1.0/2688.0*H02L8     1          - (211.*NB/3628800. + 7.*WMN/259200.)*H04L10        YDYDT = 1.0/5760.0*H02L9     1      - (59.*NB/4435200. + 31.*WMN/2217600.)*H04L11      ELSE        IF (NB .EQ. 0.0)     1   YDYT = 1.0/6.0*VSL3/H0W - 1.0/6.0*VSL3CX/H0W        IF (NB .NE. 0.0)     1   YDYT = 0.5*VSDSM/H05N - 0.5*VSLDC1/H02N        YDYCE = - VSCDC1/H02F + VSDCM/H03F     1   - 2.0*NB*VSSDS1/WM5N        YDYCT = 2.0*VSSDC1/H02F - VSCDS1/H02F     1   - VSDSM/H05F        YDYSE = - 0.5*VSCDS1/H02W + 0.5*VSDSM/H05W     1   + 0.5*VSCDS1/H02F - VSSDC1/H02F     2   + 0.5*VSDSM/H05F        YDYST = 2.0*VSDDC1/H03F - VSSDS1/H02F        YDYDE = 0.5*VSLDS1/H0W - VSDDC1/H02F     1   + 2.0*NB*VSSDS1/H0WF      IF (NB .EQ. 0.0) TERM1 = (0.05*L5 + (H02L3 - 18.0*L)*CX/H04     1 - (6.0*H02L2 - 24.0)*SX/H04 - 6.0*L/H04)/(6.0*H02)      IF (NB .NE. 0.0) TERM1 = 0.5*VSDSM/(NB*WMN*H06)     1 - 0.5*VSLDC1/(NB*WMN*H03)        YDYDT = TERM1     1   - 2.0*VSSDC1/H03WF + VSCDS1/H03WF     2   + VSDSM/H06WF      ENDIFC      YCQE = 0.5*VSLCC1 + 0.5*VSCSM/H02      YCQT = 0.5*VSLCS1      YCQCE = - NB*VSCSM/H02F - NB*VSCCS1/WM5N     1 + 0.5*VSCSC1 + 0.5*WMN*VSCSC1/WM5N      IF (XPND) THEN        YCQCT = 1.0/24.