 + 0.5*WMN*VSSDC1/WM5N      IF (XPND) THEN        YDQCT = 1.0/120.0*H0L6 - (NB/1120. + WMN/672.)*H03L8        YDQSE = 1.0/120.0*H0L6 - (11.*NB/6720. + WMN/1344.)*H03L8        YDQST = 1.0/252.0*H0L7     1          - (73.*NB/181440. + 11.*WMN/25920.)*H03L9        YDQDE = 1.0/504.0*H02L7     1          - (157.*NB/362880. + WMN/6480)*H04L9        YDQDT = 1.0/896.0*H02L8     1          - (409.*NB/3628800. + WMN/10368.)*H04L10      ELSE        YDQCT = VSCDC1/H02F - VSDCM/H03F     1   + 0.5*VSSDS1 + 0.5*WMN*VSSDS1/WM5N        YDQSE = 0.5*VSDDC1/H0 - NB*VSSDS1/WM5N     1   - 0.5*VSCDC1/H02F + 0.5*VSDCM/H03F        YDQST = 0.5*VSDDS1/H0 + VSSDC1/H02F     1   - 0.5*VSCDS1/H02F - 0.5*VSDSM/H05F        YDQDE = NB*VSCDS1/H0WF + NB*VSDSM/H04WF     1   + 0.5*VSLDC1/H0W - 0.5*VSSDC1/H0W     2   - 0.5*VSSDC1/H0F + 0.5*VSDSM/H04W        YDQDT = VSDDC1/H02F + 0.5*VSLDS1/H0W     1   - 0.5*VSSDS1/H0W - 0.5*VSSDS1/H0F      ENDIFC      YEXI = VSDCM/H02      YEXC = 0.5*VSLSC1      IF (XPND) THEN        YEXS = 1.0/120.0*L5 - (11.*NB/5040. + WMN/2520.)*H02L7        YEXD = 1.0/720.0*H0L6 - (NB/2520. + WMN/20160.)*H03L8      ELSE        YEXS = 0.5*VSSCM/H04W - 0.5*VSLCC1/H02W        YEXD = VSDCM/H03W - 0.5*VSLSC1/H0W      ENDIF      YEXCC = 1./3.*VSCDC1/H0 + 2./3.*VSDCM/H02      YEXCS = 1./3.*VSSDC1/H0      IF (XPND) THEN        YEXCD = 1.0/720.0*H0L6 - (NB/2520. + WMN/5040.)*H03L8      ELSE        YEXCD = 0.5*VSLSC1/H0W - 1./3.*VSCDC1/H02W     1   - 2./3.*VSDCM/H03W      ENDIF      YEXSS = 1./3.*VSDDC1/H02      IF (XPND) THEN        YEXSD = 1.0/1680.0*H0L7 - (11.*NB/60480. + WMN/20160.)*H03L9        YEXDD = 1.0/6720.0*H02L8     1          - (29.*NB/604800. + WMN/100800.)*H04L10        YEXEE = 1.0/24.0*L4 - (NB/80. + WMN/720.)*H02L6        YEXET = 1.0/120.0*L5 - (NB/336. + WMN/5040.)*H02L7        YEXTT = 1.0/360.0*L6 - (NB/1008. + WMN/20160.)*H02L8      ELSE        YEXSD = - 0.5*VSLCC1/H03W2     1   + 1./3.*VSCSC1/H03W2 + 1./6.*VSSCM/H05W2        YEXDD = 1./3.*VSCDC1/H03W2     1   + 5./3.*VSDCM/H04W2 - VSLSC1/H02W2        YEXEE = 0.5*VSDCM/H02 - 0.5*VSCCM/H02F     1   - 0.5*VSCY/H02F + VSCCC3/H02F        YEXET = - VSSCM/H04F + VSCCS3/H02F        YEXTT = 2.0*VSCCM/H04WF - 2.0*VSCY/H04WF     1   + VSCSS3/H02F      ENDIFC      YTXI = VSDSM/H04      YTXC = 0.5*VSLSS1      IF (XPND) THEN        YTXS = 1.0/180.0*L6 - (NB/1680. + WMN/3360.)*H02L8        YTXD = 1.0/1008.0*H0L7 - (NB/9072. + WMN/25920.)*H03L9      ELSE        YTXS = 0.5*VSSSM/H04W - 0.5*VSLCS1/H02W        YTXD = VSDSM/H05W - 0.5*VSLSS1/H0W      ENDIF      YTXCC = 2./3.*VSDSM/H04 + 1./3.*VSCDS1/H0      YTXCS = 1./3.*VSSDS1/H0      IF (XPND) THEN        YTXCD = 1.0/1008.0*H0L7 - (NB/9072. + WMN/6480.)*H03L9      ELSE        YTXCD = 0.5*VSLSS1/H0W - 1./3.*VSCDS1/H02W     1   - 2./3.*VSDSM/H05W      ENDIF      YTXSS = 1./3.*VSDDS1/H02      IF (XPND) THEN        YTXSD = 1.0/2240.0*H0*L8     1          - (31.*NB/604800. + WMN/25200.)*H03L10        YTXDD = 1.0/8640.0*H02L9     1          - (13.*NB/950400. + WMN/123200.)*H04L11        YTXEE = 0.025*L5 - (23.*NB/5040. + WMN/1008.)*H02L7        YTXET = 1.0/180.0*L6 - (NB/840. + WMN/6720.)*H02L8        YTXTT = 1.0/504.0*L7 - (17.*NB/45360. + WMN/25920.)*H02L9      ELSE        YTXSD = 1./3.*VSCSS1/H03W2     1   + 1./6.*VSSSM/H05W2 - 0.5*VSLCS1/H03W2        YTXDD = 5./3.*VSDSM/H06W2     1   + 1./3.*VSCDS1/H03W2 - VSLSS1/H02W2        YTXEE = 0.5*VSDSM/H04 - 0.5*VSCSM/H04F     1   + VSCCS3/H02F - 0.5*VSSY/H04F        YTXET = - VSSSM/H04F + VSCSS3/H02F        YTXTT = - 2.0*VSDSM/H06F + VSSSS3/H02F      ENDIFC      YEPI = VSSCM/H02      YEPC = 0.5*VSLCC1 + 0.5*VSSCM/H02      YEPS = 0.5*VSLSC1      IF (XPND) THEN        YEPD = 1.0/120.0*H0L5 - (11.*NB/5040. + WMN/2520.)*H03L7      ELSE        YEPD = 0.5*VSSCM/H03W - 0.5*VSLCC1/H0W      ENDIF      YEPCC = 2./3.*VSCSC1 + 1./3.*VSSCM/H02      YEPCS = 1./3.*VSDCM/H02 + 2./3.*VSCDC1/H0      IF (XPND) THEN       