/H02F        QCYSE = 0.5*VPCDS1/H0 - VPCSC1/H02F     1   + 0.5*VPCSM/H02F + 0.5*VPCCS1/H02F        QCYST = 2.0*VPCDC1/H03F - VPCSS1/H02F        QCYDE = 0.5*VPLCS1/H0W - VPCDC1/H02F     1   + 2.0*NB*VPCSS1/H0WF        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*VPL3CX/H0        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VPCSM/H03NW - 0.5*VPLCC1/H03NW        QCYDT = TERM1     1   - 2.0*VPCSC1/H03WF + VPCSM/H03WF     2   + VPCCS1/H03WF      ENDIFC      QSYE = 0.5*VPLSS1      IF (XPND) THEN        QSYT = 1.0/30.0*L5 - (NB/315. + WMN/252.)*H02L7        QSYCE = 0.125*L4 - (13.*NB/720. + WMN/48.)*H02L6        QSYCT = 1.0/30.0*L5 - (NB/315. + 19.*WMN/2520.)*H02L7        QSYSE = 1.0/30.0*L5 - (NB/180. + 13.*WMN/2520.)*H02L7        QSYST = 1.0/72.0*L6 - (13.*NB/10080. + 7.*WMN/2880.)*H02L8        QSYDE = 1.0/144.0*H0L6 - (3.*NB/2240. + WMN/960.)*H03L8        QSYDT = 1.0/280.0*H0L7     1          - (61.*NB/181440. + 13.*WMN/22680.)*H03L9      ELSE        IF (NB .EQ. 0.0) QSYT = 1.0/6.0*VPL3SX        IF (NB .NE. 0.0)     1   QSYT = 0.5*VPSSM/H04N - 0.5*VPLSC1/H02N        QSYCE = VPSCM/H02F - VPCSC1/H02F     1   - 2.0*NB*VPSSS1/WM5N        QSYCT = 2.0*VPSSC1/H02F - VPCSS1/H02F     1   - VPSSM/H04F        QSYSE = 0.5*VPSDS1/H0 - VPSSC1/H02F     1   + 0.5*VPCSS1/H02F + 0.5*VPSSM/H04F        QSYST = 2.0*VPSDC1/H03F - VPSSS1/H02F        QSYDE = 0.5*VPLSS1/H0W - VPSDC1/H02F     1   - 0.5*VPSSS1/H0W + 0.5*VPSSS1/H0F        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*VPL3SX/H0        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VPSSM/H05NW - 0.5*VPLSC1/H03NW        QSYDT = TERM1     1   - 2.0*VPSSC1/H03WF + VPCSS1/H03WF     2   + VPSSM/H05WF      ENDIFC      QDYE = 0.5*VPLDS1      IF (XPND) THEN        QDYT = 1.0/72.0*H0L6 - (13.*NB/10080. + WMN/1152.)*H03L8        QDYCE = 0.05*H0L5 - (NB/140. + WMN/168.)*H03L7        QDYCT = 1.0/72.0*H0L6 - (13.*NB/10080. + 7.*WMN/2880.)*H03L8        QDYSE = 1.0/72.0*H0L6 - (47.*NB/20160. + WMN/720.)*H03L8        QDYST = 1.0/168.0*H0L7 - (11.*NB/20160. + WMN/1440.)*H03L9        QDYDE = 1.0/336.0*H02L7     1          - (211.*NB/362880. + 7.*WMN/25920.)*H04L9        QDYDT = 1.0/640.0*H02L8     1          - (59.*NB/403200. + 31.*WMN/201600.)*H04L10      ELSE        IF (NB .EQ. 0.0) QDYT = 1.0/6.0*(VPL3 - VPL3CX)/H0        IF (NB .NE. 0.0)     1   QDYT = 0.5*VPDSM/H03N - 0.5*VPLDC1/H02N        QDYCE = - VPCDC1/H02F + VPDCM/H03F     1   - 2.0*NB*VPSDS1/WM5N        QDYCT = 2.0*VPSDC1/H02F - VPCDS1/H02F     1   - VPDSM/H03F        QDYSE = 0.5*VPDDS1/H0 + 0.5*VPCDS1/H02F     1   - VPSDC1/H02F + 0.5*VPDSM/H03F        QDYST = - 2.0*VPCDC1/H04WF - VPSDS1/H02F     1   + 2.0*VPDCM/H05WF        QDYDE = 0.5*VPLDS1/H0W - VPDDC1/H02F     1   + 2.0*NB*VPSDS1/H0WF        IF (NB .EQ. 0.0) TERM1 = 1.0/6.0*(VPL3 - VPL3CX)/H02        IF (NB .NE. 0.0)     1   TERM1 = 0.5*VPDSM/H04NW - 0.5*VPLDC1/H03NW        QDYDT = TERM1     1   - 2.0*VPSDC1/H03WF + VPCDS1/H03WF     2   + VPDSM/H04WF      ENDIFC      QCQE = 0.5*VPLCC1 + 0.5*VPCSM      QCQT = 0.5*VPLCS1      QCQCE = - NB*VPCSM/WM5N - NB*VPCCS1/WM5N     1 + 0.5*VPCSC1 + 0.5*WMN*VPCSC1/WM5N      IF (XPND) THEN        QCQCT = 1.0/6.0*L3 - (NB/40. + 3.*WMN/40.)*H02L5        QCQSE = 1.0/6.0*L3 - (NB/24. + 7.*WMN/120.)*H02L5        QCQST = 1.0/12.0*L4 - (NB/90. + WMN/30.)*H02L6        QCQDE = 1.0/24.0*H0*L4 - (NB/90. + 11.*WMN/720.)*H03L6        QCQDT = 0.025*H0L5 - (NB/315. + 5.*WMN/504.)*H03L7      ELSE        QCQCT = - VPCCM/H02F + VPCCC1/H02F     1   + 0.5*VPCSS1 + 0.5*WMN*VPCSS1/WM5N        QCQSE = - NB*VPCSS1/WM5N + 0.5*VPCCM/H02W     1   + 0.5*VPCCM/H02F - 0.5*VPCCC1/H02W     2   - 0.5*VPCCC1/H02F        QCQST = 0.5*VPCDS1/H0 + VPCSC1/H02F     1   - 0.5*VPCSM/H02F - 0.5*VPCCS1/H02F        QCQDE = NB*VPCSM/H0WF + NB*VPCCS1/H0WF     1   + 0.5*VPLCC1/H0W - 0.5*VPCSC1/H0W     2   - 0.5*VPCSC1/H0F + 0.5*VPCSM/H0W        QCQDT = 0.5*VPLCS1/H0W - 0.5*VPCSS1/H0W     1   + VPCDC1/H02F - 0.5*VPCSS1/H0F      ENDIFC      QSQE = 0.5*VPLSC1 + 0.5*VPSSM/H02      QSQT = 0.5*VPLSS1      QSQCE = - NB*VPCSS1/WM5N - NB*VPSSM/H02F     1 + 0.5*VPSSC1 + 0.5*WMN*VPSSC1/WM5N      IF (XPND) THEN        QSQCT = 0.125*L4 - (13*NB/720. + 5.*WMN/144.)*H02L6        QSQSE = 0.125*L4 - (23.*NB/720. + WMN/48.)*H02L6        QSQST = 1.0/15.0*L5 - (11.*NB/1260. + 4.*WMN/315.)*H02L7        QSQDE = 1.0/30.0*H0L5 - (23.*NB + 13.*WMN)*H03L7/2520.        QSQDT = 1.0/48.0*H0L6 - (53.*NB/20160. + WMN/288.)*H03L8      ELSE        QSQCT = VPCSC1/H02F - VPSCM/H02F     1   + 0.5*VPSSS1 + 0.5*WMN*VPSSS1/WM5N        QSQSE = 0.5*VPSDC1/H0 - NB*VPSSS1/WM5N     1   - 0.5*VPCSC1/H02F + 0.5*VPSCM/H02F        QSQST = 0.5*VPSDS1/H0 + VPSSC1/H02F     1   - 0.5*VPCSS1/H02F - 0.5*VPSSM/H04F        QSQDE = NB*VPCSS1/H0WF + NB*VPSSM/H03WF     1   + 0.5*VPLSC1/H0W - 0.5*VPSSC1/H0W     2   - 0.5*VPSSC1/H0F + 0.5*VPSSM/H03W        QSQDT = 0.5*VPLSS1/H0W + VPSDC1/H02F     1   - 0.5*VPSSS1/H0W - 0.5*VPSSS1/H0F      ENDIFC      QDQE = 0.5*VPLDC1 + 0.5*VPDSM/H0      QDQT = 0.5*VPLDS1      QDQCE = - NB*VPCDS1/WM5N - NB*VPDSM/H0F     1 + 0.5*VPSDC1 + 0.5*WMN*VPSDC1/WM5N      IF (XPND) THEN        QDQCT = 0.05*H0L5 - (NB/140. + WMN/84.)*H03L7        QDQSE = 0.05*H0L5 - (11.*NB/840. + WMN/168.)*H03L7        QDQST = 1.0/36.0*H0L6     1          - (73.*NB/20160. + 11.*WMN/2880.)*H03L8        QDQDE = 1.0/72.0*H02L6 - (157.*NB/40320. + WMN/720.)*H04L8        QDQDT = 1.0/112.0*H02L7     1          - (409.*NB/362880. + 5.*WMN/5184.)*H04L9      ELSE        QDQCT = VPCDC1/H02F - VPDCM/H03F     1   + 0.5*VPSDS1 + 0.5*WMN*VPSDS1/WM5N        QDQSE = 0.5*VPDDC1/H0 - NB*VPSDS1/WM5N     1   - 0.5*VPCDC1/H02F + 0.5*VPDCM/H03F        QDQST = 0.5*VPDDS1/H0 + VPSDC1/H02F     1   - 0.5*VPCDS1/H02F - 0.5*VPDSM/H03F        QDQDE = NB*VPCDS1/H0WF + NB*VPDSM/H02WF     1   + 0.5*VPLDC1/H0W - 0.5*VPSDC1/H0W     2   - 0.5*VPSDC1/H0F + 0.5*VPDSM/H02W        QDQDT = VPDDC1/H02F + 0.5*VPLDS1/H0W     1   - 0.5*VPSDS1/H0W - 0.5*VPSDS1/H0F      ENDIFC      QEXI = VPDCM/H02      QEXC = 0.5*VPLSC1      IF (XPND) THEN        QEXS = 1.0/24.0*L4 - (11.*NB/720. + WMN/360.)*H02L6        QEXD = 1.0/120.0*H0L5 - (NB/315. + WMN/2520.)*H03L7      ELSE        QEXS = 0.5*VPSCM/H02W - 0.5*VPLCC1/H02W        QEXD = VPDCM/H03W - 0.5*VPLSC1/H0W      ENDIF      QEXCC = 1./3.*VPCDC1/H0 + 2./3.*VPDCM/H02      QEXCS = 1./3.*VPSDC1/H0      IF (XPND) THEN        QEXCD = 1.0/120.0*H0L5 - (NB/315. + WMN/630.)*H03L7      ELSE        QEXCD = 0.5*VPLSC1/H0W - 1./3.*VPCDC1/H02W     1   - 2./3.*VPDCM/H03W      ENDIF      QEXSS = 1./3.*VPDDC1/H02      IF (XPND) THEN        QEXSD = 1.0/240.0*H0L6 - (11.*NB/6720. + WMN/2240.)*H03L8        QEXDD = 1.0/840.0*H02L7     1          - (29.*NB/60480. + WMN/10080.)*H04L9      ELSE        QEXSD = - 0.5*VPLCC1/H03W2     1   + 1./3.*VPCSC1/H03W2 + 1./6.*VPSCM/H03W2        QEXDD = 1./3.*VPCDC1/H03W2 + 5./3.*VPDCM/H04W2     1   - VPLSC1/H02W2      ENDIF      IF (XPND) THEN        QEXEE = 1.0/6.0*L3 - (3.*NB/40. + WMN/120.)*H02L5        QEXET = 1.0/24.0*L4 - (NB/48. + WMN/720.)*H02L6        QEXTT = 1.0/60.0*L5 - (NB/126. + WMN/2520.)*H02L7      ELSE        QEXEE = 0.5*VPDCM/H02 - 0.5*VPCCM/H02F     1   - 0.5*VPCY/H02F + VPCCC3/H02F        QEXET = - VPSCM/H02F + VPCCS3/H02F        QEXTT = 2.0*VPCCM/H04WF     1   - 2.0*VPCY/H04WF + VPCSS3/H02F      ENDIFC      QTXI = VPDSM/H02      QTXC = 0.5*VPLSS1      IF (XPND) THEN        QTXS = 1.0/30.0*L5 - (NB/210. + WMN/420.)*H02L7        QTXD = 1.0/144.0*H0L6 - (NB/1008. + WMN/2880.)*H03L8      ELSE        QTXS = 0.5*VPSSM/H04W - 0.5*VPLCS1/H02W        QTXD = VPDSM/H03W - 0.5*VPLSS1/H0W      ENDIF      QTXCC = 2./3.*VPDSM/H02 + 1./3.*VPCDS1/H0      QTXCS = 1./3.*VPSDS1/H0      IF (XPND) THEN        QTXCD = 1.0/144.0*H0L6 - (NB/1008. + WMN/720.)*H03L8      ELSE        QTXCD = 0.5*VPLSS1/H0W - 1./3.*VPCDS1/H02W     1   - 2./3.*VPDSM/H03W      ENDIF      QTXSS = 1./3.*VPDDS1/H02      IF (XPND) THEN        QTXSD = 1.0/280.0*H0L7 - (31.*NB/60480. + WMN/2520.)*H03L9        QTXDD = 1.0/960.0*H02L8     1          - (13.*NB/86400. + WMN/11200.)*H04L10      ELSE        QTXSD = 1./3.*VPCSS1/H03W2     1   + 1./6.*VPSSM/H05W2 - 0.5*VPLCS1/H03W2        QTXDD = 5./3.*VPDSM/H04W2     1   + 1./3.*VPCDS1/H03W2 - VPLSS1/H02W2      ENDIF      IF (XPND) THEN        QTXEE = 0.125*L4 - (23.*NB/720. + WMN/144.0)*H02L6        QTXET = 1.0/30.0*L5 - (NB/105. + WMN/840.)*H02L7        QTXTT = 1.0/72.0*L6 - (17.*NB/5040. + WMN/2880.)*H02L8      ELSE        QTXEE = 0.5*VPDSM/H02 - 0.5*VPCSM/H02F     1   + VPCCS3/H02F - 0.5*VPSY/H02F        QTXET = - VPSSM/H04F + VPCSS3/H02F        QTXTT = - 2.0*VPDSM/H04F + VPSSS3/H02F      ENDIFC      QEPI = VPSCM      QEPC = 0.5*VPLCC1 + 0.5*VPSCM      QEPS = 0.5*VPLSC1      IF (XPND) THEN        QEPD = 1.0/24.0*H0*L4 - (11.*NB/720. + WMN/360.)*H03L6      ELSE        QEPD = 0.5*VPSCM/H0W - 0.5*VPLCC1/H0W      ENDIF      QEPCC = 2./3.*VPCSC1 + 1./3.*VPSCM      QEPCS = 1./3.*VPDCM/H02 + 2./3.*VPCDC1/H0      IF (XPND) THEN        QEPCD = 1.0/24.0*H0*L4 - (11.*NB/720. + WMN/90.)*H03L6      ELSE        QEPCD = 0.5*VPLCC1/H0W - 2./3.*VPCSC1/H0W     1   + 1./6.*VPSCM/H0W      ENDIF      QEPSS = 2./3.*VPSDC1/H0      IF (XPND) THEN        QEPSD = 0.025*H0L5 - (NB/105. + WMN/280.)*H03L7        QEPDD = 1.0/120.0*H02L6 - (11.*NB/3360. + WMN/1120.)*H04L8      ELSE        QEPSD = 0.5*VPLSC1/H0W - 2./3.*VPCDC1/H02W     1   - 1./3.*VPDCM/H03W        QEPDD = 2./3.*VPCSC1/H02W2     1   + 1./3.*VPSCM/H02W2 - VPLCC1/H02W2      ENDIF      QEPEE = 0.5*VPSCM + 0.5*WMN*VPSCM/WM5N     1 - 2.*NB*VPCCS3/WM5N      IF (XPND) THEN        QEPET = 1.0/6.0*L3 - (11.*NB + WMN)*H02L5/120.        QEPTT = 1.0/12.0*L4 - (NB/24. + WMN/360.)*H02L6      ELSE        QEPET = - VPCCM/H02F - VPCY/H02F     1   + 2.*VPCCC3/H02F        QEPTT = - 2.0*VPSCM/H02F + 2.*VPCCS3/H02F      ENDIFC      QTPI = VPSSM/H02      QTPC = 0.5*VPLCS1 + 0.5*VPSSM/H02      QTPS = 0.5*VPLSS1      IF (XPND) THEN        QTPD = 1.0/30.0*H0L5 - (NB/210. + WMN/420.)*H03L7      ELSE        QTPD = - 0.5*VPLCS1/H0W + 0.5*VPSSM/H03W      ENDIF      QTPCC = 2./3.*VPCSS1 + 1./3.*VPSSM/H02      IF (XPND) THEN        QTPCS = 0.125*L4 - (13.*NB/720. + 5.*WMN/144.)*H02L6        QTPCD = 1.0/30.0*H0L5 - (NB/210. + WMN/105.)*H03L7      ELSE        QTPCS = 1./3.*VPCSM/H02W - 2./3.*VPCCS1/H02W     1   + 1./3.*VPSY/H02W        QTPCD = 0.5*VPLCS1/H0W - 2./3.*VPCSS1/H0W     1   + 1./6.*VPSSM/H03W      ENDIF      QTPSS = 2./3.*VPSDS1/H0      IF (XPND) THEN        QTPSD = 1.0/48.0*H0L6 - (NB/336. + WMN/320.)*H03L8        QTPDD = 1.0/140.0*H02L7     1          - (31.*NB/30240. + WMN/1260.)*H04L9        QTPEE = 1.0/3.0*L3 - (7.*NB/60. + WMN/30.)*H02L5        QTPET = 0.125*L4 - (11.*NB/240. + WMN/144.)*H02L6        QTPTT = 1.0/15.0*L5 - (2.*NB/105. + WMN/420.)*H02L7      ELSE        QTPSD = 0.5*VPLSS1/H0W - 2./3.*VPCDS1/H02W     1   - 1./3.*VPDSM/H03W        QTPDD = - VPLCS1/H02W2 + 2./3.*VPCSS1/H02W2     1   + 1./3.*VPSSM/H04W2        QTPEE = 0.5*WMN*VPSSM/H02F - 2.*NB*VPCSS3/WM5N     1   + 0.5*VPSSM/H02        QTPET = - VPCSM/H02F + 2.*VPCCS3/H02F     1   - VPSY/H02F        QTPTT = - 2.0*VPSSM/H04F + 2.*VPCSS3/H02F      ENDIF      RETURN      END